package com.payx.app.ui.screens

import android.util.Base64
import java.nio.ByteBuffer
import java.nio.ByteOrder

/**
 * Precomputed Natural Earth land coordinates for rotating particle globe.
 */
internal object GlobeData {
    private const val ENCODED_POINTS = ""

    val points: FloatArray by lazy {
        val bytes = Base64.decode(ENCODED_POINTS, Base64.DEFAULT)
        val byteBuffer = ByteBuffer.wrap(bytes).order(ByteOrder.BIG_ENDIAN)
        val shortBuffer = byteBuffer.asShortBuffer()
        val count = shortBuffer.remaining() / 2
        val result = FloatArray(count * 2)
        val toRad = (Math.PI / 180.0).toFloat()
        for (i in 0 until count) {
            val latDeg = shortBuffer.get().toFloat() / 100f
            val lonDeg = shortBuffer.get().toFloat() / 100f
            result[i * 2] = latDeg * toRad
            result[i * 2 + 1] = lonDeg * toRad
        }
        result
    }
}
